import{_ as t,o as i,c as a,al as o}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"AI Pull Request Review","description":"","frontmatter":{},"headers":[],"relativePath":"en/test_and_ci/ai_review.md","filePath":"en/test_and_ci/ai_review.md"}'),s={name:"en/test_and_ci/ai_review.md"};function n(r,e,l,h,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="ai-pull-request-review" tabindex="-1">AI Pull Request Review <a class="header-anchor" href="#ai-pull-request-review" aria-label="Permalink to &quot;AI Pull Request Review&quot;">​</a></h1><p>PX4 maintainers can ask an AI model to review a pull request. The review is posted on the PR as a regular GitHub review comment, with inline comments on specific lines where it found problems.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is a trial. Reviews can be wrong, and the tool may change as we learn what works. Feedback from maintainers is welcome in the maintainers&#39; channel or as an issue.</p></div><h2 id="who-can-use-it" tabindex="-1">Who Can Use It <a class="header-anchor" href="#who-can-use-it" aria-label="Permalink to &quot;Who Can Use It&quot;">​</a></h2><p>Only people with write, maintain or admin access to the PX4-Autopilot repository can start a review. In practice this is the <a href="https://github.com/orgs/PX4/teams/dev-team" target="_blank" rel="noreferrer">Dev Team</a> (see <a href="./../contribute/maintainers">Maintainers</a>). A request from anyone else is ignored.</p><h2 id="starting-a-review" tabindex="-1">Starting a Review <a class="header-anchor" href="#starting-a-review" aria-label="Permalink to &quot;Starting a Review&quot;">​</a></h2><p>Post a comment on the open pull request that contains only this text:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!ai-review</span></span></code></pre></div><p>The comment must contain nothing else. A sentence that mentions the command, a quote of it, or the command with a typo does not start a review.</p><p>To pick the model or the effort level, add options on the same line:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!ai-review model=sonnet effort=high</span></span></code></pre></div><ul><li><code>model</code>: <code>opus</code> (the default) or <code>sonnet</code>.</li><li><code>effort</code>: <code>low</code>, <code>medium</code>, <code>high</code>, <code>xhigh</code> (the default) or <code>max</code>.</li></ul><p>Both options apply to the first review pass only. The second pass that confirms findings always uses Claude Opus at <code>high</code> effort (set in <code>Tools/ci/ai_review/models.json</code>), and its cost is included in the total.</p><p>Within a few seconds your comment gets a 👀 reaction, which means the review has started. When it finishes, the comment gets 🚀, or 😕 if the run failed. A review takes about 5 to 15 minutes, depending on the size of the PR. While it runs, an &quot;AI PR Review&quot; entry in the PR&#39;s checks shows its progress and links to the workflow run. This check is informational and never blocks a merge.</p><p>You can also start a review from the <strong>Actions</strong> tab: open the <a href="https://github.com/PX4/PX4-Autopilot/actions/workflows/pr-ai-review.yml" target="_blank" rel="noreferrer">AI PR Review</a> workflow, select <strong>Run workflow</strong> and enter the PR number.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use reviews where a second opinion matters most: flight-critical code, new boards, large changes, and contributions from people new to the project. Every review costs money (see <a href="#cost">Cost</a>).</p></div><h2 id="what-the-review-contains" tabindex="-1">What the Review Contains <a class="header-anchor" href="#what-the-review-contains" aria-label="Permalink to &quot;What the Review Contains&quot;">​</a></h2><p>For an example, see <a href="https://github.com/PX4/PX4-Autopilot/pull/28901" target="_blank" rel="noreferrer">PR #28901</a>.</p><ul><li>Inline comments on specific lines, for findings that a second, independent model pass confirmed with high confidence. When a small change fully fixes the problem, the comment includes a suggestion that the author can apply with one click.</li><li>A &quot;Before merge&quot; list for issues with the pull request as a whole, such as missing test evidence, a description that does not match the change, or missing upgrade notes or documentation.</li><li>A checklist covering whether the problem is real, test evidence, the description, compatibility, and documentation.</li><li>A collapsed list of lower-confidence findings that may still be worth checking.</li><li>The cost of the review, the model used and how long it took, at the bottom.</li></ul><p>The review is always a comment. It never approves a pull request or requests changes: maintainers decide.</p><p>Running the review again on the same pull request collapses the previous review&#39;s summary and marks it as superseded. Its inline comments stay on the pull request and may refer to an older commit.</p><p>If the model&#39;s safety filter declines to review a pull request, which occasionally happens, the bot posts that no review was done and quotes the reason it was given.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Each review is billed to the PX4 project. So far, reviews have cost between about $0.60 for a small change and $5 to $8 for a large board addition with Claude Opus, and less with Claude Sonnet. The exact cost is shown at the bottom of every review.</p><p>Claude Sonnet is faster and cheaper, but in testing it missed real problems that Claude Opus found, so Opus is the default.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>A small job checks that the comment is exactly the command and that the commenter has write access, using the GitHub API. If either check fails, nothing else runs.</li><li>The review job runs <em>Claude Code</em> with Claude Opus on Amazon Bedrock, on a PX4 CI runner. It reads the pull request, the surrounding code, linked issues, commit messages, CI status and git history. It reviews against the same criteria as the <code>review-pr</code> skill used by maintainers locally, plus the contribution requirements (test evidence, an accurate description, upgrade notes and documentation).</li><li>A second model pass checks each finding against the code. Only findings it confirms with high confidence are posted as inline comments.</li><li>The result is handed to the existing PR review poster workflow, which posts it on the pull request.</li></ol><p>The pull request is treated as untrusted input:</p><ul><li>The reviewer can only read files and run a few read-only commands. It never builds or runs the pull request&#39;s code.</li><li>When it needs to check a calculation, it runs Python in an isolated <code>px4-dev</code> container with no network access and no credentials.</li><li>The review job has no write access to GitHub; only the separate posting workflow does.</li><li>The review code always comes from <code>main</code>. A pull request cannot change how it is reviewed, and changes to the review tool only take effect once they are merged.</li></ul><h2 id="changing-the-review" tabindex="-1">Changing the Review <a class="header-anchor" href="#changing-the-review" aria-label="Permalink to &quot;Changing the Review&quot;">​</a></h2><p>The code is in <a href="https://github.com/PX4/PX4-Autopilot/tree/main/Tools/ci/ai_review" target="_blank" rel="noreferrer"><code>Tools/ci/ai_review/</code></a>, a Python package with its own <a href="https://github.com/PX4/PX4-Autopilot/blob/main/Tools/ci/ai_review/README.md" target="_blank" rel="noreferrer">README</a>. The workflow is <a href="https://github.com/PX4/PX4-Autopilot/blob/main/.github/workflows/pr-ai-review.yml" target="_blank" rel="noreferrer"><code>.github/workflows/pr-ai-review.yml</code></a>.</p><ul><li>The models and their default effort levels are set in <code>Tools/ci/ai_review/models.json</code>.</li><li>The review criteria shared with the <code>review-pr</code> skill are in <code>.agents/skills/review-pr/review-criteria.md</code>.</li><li>The CI-only prompts are in <code>Tools/ci/ai_review/prompts/</code>.</li></ul><p>Pull requests to improve the review are welcome.</p>',33)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
